do $MIG$
declare
  spec jsonb := $SPEC${"push": [[{"ex": "b7e5bad3-0d5e-4797-9113-f2e266a307e4", "reps": "3", "rest": 20, "rpe": null, "notes": "Jump Shrugs · 30% 1RM · max intent", "sets": [4, 4, 4, 6, 2]}], [{"ex": "a0348938-ab5d-4100-a461-a8fa2f49770d", "reps": "5", "rest": 20, "rpe": 8, "notes": "Trap Bar Deadlift · 80% 1RM · VBT 0.65 m/s (cut 0.5525, 0.15)", "sets": [3, 3, 4, 4, 1]}, {"ex": "5fdead4e-f7a1-46ca-824d-d62daa6cba0e", "reps": "5", "rest": 120, "rpe": null, "notes": "Drop jumps · max intent", "sets": [3, 3, 4, 4, 1]}], [{"ex": "dacd6f95-7bf2-49c0-8d4f-a4a7f92e2795", "reps": "5", "rest": 20, "rpe": 8, "notes": "Bench press · 80% 1RM · VBT 0.65 m/s (cut 0.5525, 0.15)", "sets": [3, 3, 4, 4, 1]}, {"ex": "3dc4eaa8-bfcd-4d0a-ab66-ea2350f02e36", "reps": "5", "rest": 120, "rpe": null, "notes": "Plyo push-up · max intent", "sets": [3, 3, 4, 4, 1]}], [{"ex": "453f0f6b-ab72-4b84-bd87-4e550dc8b159", "reps": "5 each leg", "rest": 30, "rpe": 7, "notes": "Box Step up · 65% 1RM · max intent", "sets": [2, 2, 2, 2, 1]}, {"ex": "98fd1fe1-b126-4221-953b-18093c8f40ba", "reps": "5", "rest": 90, "rpe": 7, "notes": "Push press · 65% 1RM · max intent", "sets": [2, 2, 2, 2, 1]}], [{"ex": "6868a6cc-351e-4af4-a2fd-783760c78722", "reps": "6-8 each leg", "rest": 15, "rpe": null, "notes": "Adductor valslide lunge · controlled", "sets": [1, 1, 1, 1, 1]}, {"ex": "e8088efe-5f14-4578-bba5-6c3ac300c5da", "reps": "8-10 each side", "rest": 30, "rpe": null, "notes": "Pallof press · controlled", "sets": [1, 1, 1, 1, 1]}]], "pull": [[{"ex": "5b8439b5-5d72-480a-b201-57459b02bd27", "reps": "3", "rest": 20, "rpe": 8, "notes": "Mid-thigh clean pull · 80% 1RM · max intent", "sets": [4, 4, 4, 6, 6]}], [{"ex": "0cfbd9c6-0305-47f9-9f68-1aa8cd137207", "reps": "5", "rest": 30, "rpe": 8, "notes": "RDL or single leg RDL · 80% 1RM · VBT 0.65 m/s (cut 0.5525, 0.15)", "sets": [2, 2, 2, 2, 2]}, {"ex": "7eb0480c-05dd-4676-a52a-c83f92122630", "reps": "3 each leg", "rest": 180, "rpe": null, "notes": "MB Moye Start · max intent", "sets": [2, 3, 4, 4, 1]}], [{"ex": "60536284-7bfa-440f-8eba-11b756afbf66", "reps": "5", "rest": 30, "rpe": null, "notes": "Chin ups · max intent", "sets": [2, 3, 4, 4, 1]}, {"ex": "39a023dd-e535-4f8c-8622-456cdda06ed0", "reps": "5", "rest": 180, "rpe": null, "notes": "Barbell hip thrust · max intent", "sets": [2, 3, 4, 4, 1]}], [{"ex": "3be8a64a-196f-43d7-b8b2-a8f5f3c096bf", "reps": "6-8 each leg", "rest": 15, "rpe": null, "notes": "Copenhagen adductor · controlled", "sets": [1, 1, 1, 2, 1]}, {"ex": "d17620aa-2bfa-4ed6-8953-f3b0d8a50919", "reps": "6-8 each side", "rest": 30, "rpe": null, "notes": "R. Overhead side plank · controlled", "sets": [1, 1, 1, 2, 1]}, {"ex": "de013fbe-64f4-4ccb-a308-fa9fb58ab135", "reps": "10", "rest": 30, "rpe": null, "notes": "R. Overhead  plank · controlled", "sets": [1, 1, 1, 2, 1]}], [{"ex": "0e241007-29ec-4f9d-8113-05df033f7f76", "reps": "4-6", "rest": 90, "rpe": null, "notes": "Nordic hamstring · controlled", "sets": [1, 1, 1, 1, 1]}]], "combo1": [[{"ex": "5fa90af0-02ef-44d9-91a3-6cef4a8ff79b", "reps": "3", "rest": 20, "rpe": 7, "notes": "Mid-thigh snatch pull · 60% 1RM · max intent", "sets": [4, 4, 5, 4, 2]}], [{"ex": "a9b3f5e6-6f7a-4e6b-81b0-b34a67a6cee7", "reps": "2 each arm", "rest": 30, "rpe": null, "notes": "DB snatch · max intent", "sets": [4, 4, 5, 4, 1]}, {"ex": "7eb0480c-05dd-4676-a52a-c83f92122630", "reps": "3 each side", "rest": 60, "rpe": null, "notes": "MB obolique throw · max intent", "sets": [4, 4, 5, 4, 4]}], [{"ex": "3d08c2dd-8a8d-4830-b81b-cac1d2742035", "reps": "5 each leg", "rest": 90, "rpe": 7, "notes": "B. Split Squat · 60% 1RM · VBT 0.9 m/s (cut 0.765, 0.15)", "sets": [2, 2, 2, 2, 1]}, {"ex": "dacd6f95-7bf2-49c0-8d4f-a4a7f92e2795", "reps": "5", "rest": 90, "rpe": 7, "notes": "Bench press · 65% 1RM · VBT 0.85 m/s (cut 0.7224999999999999, 0.15)", "sets": [2, 2, 2, 2, 1]}], [{"ex": "39a023dd-e535-4f8c-8622-456cdda06ed0", "reps": "5", "rest": 30, "rpe": 8, "notes": "Barbell hip thrust · 80% 1RM · VBT 3-5 sec iso m/s", "sets": [2, 2, 2, 2, 1]}, {"ex": "e011b2e4-2c4c-402e-8504-6cee9931dc4f", "reps": "5", "rest": 60, "rpe": null, "notes": "Pull ups · max intent", "sets": [2, 2, 2, 2, 1]}], [{"ex": "d17620aa-2bfa-4ed6-8953-f3b0d8a50919", "reps": "6-8 each side", "rest": 30, "rpe": null, "notes": "R. Overhead side plank · controlled", "sets": [1, 1, 2, 1, 1]}, {"ex": "de013fbe-64f4-4ccb-a308-fa9fb58ab135", "reps": "10", "rest": 30, "rpe": null, "notes": "R. Overhead  plank · controlled", "sets": [1, 1, 2, 1, 1]}, {"ex": "e8088efe-5f14-4578-bba5-6c3ac300c5da", "reps": "8-10 each side", "rest": 30, "rpe": null, "notes": "Pallof press · controlled", "sets": [1, 1, 2, 1, 1]}], [{"ex": "0e241007-29ec-4f9d-8113-05df033f7f76", "reps": "4-6", "rest": 90, "rpe": null, "notes": "Nordic hamstring · controlled", "sets": [1, 1, 1, 1, 1]}]], "combo2": [[{"ex": "a0348938-ab5d-4100-a461-a8fa2f49770d", "reps": "3-5", "rest": 20, "rpe": 8, "notes": "Trap Bar Deadlift · 80% 1RM · VBT 0.8 m/s (cut 0.68, 0.15) · sets: 2 + 1 iso", "sets": [2, 1, 2, 2, 2]}, {"ex": "5fdead4e-f7a1-46ca-824d-d62daa6cba0e", "reps": "2-3", "rest": 120, "rpe": null, "notes": "Drop jumps · max intent", "sets": [3, 2, 3, 3, 3]}], [{"ex": "dacd6f95-7bf2-49c0-8d4f-a4a7f92e2795", "reps": "3-5", "rest": 20, "rpe": 8, "notes": "Bench press · 80% 1RM · VBT 0.65 m/s (cut 0.5525, 0.15) · sets: 2 + 1 iso", "sets": [2, 2, 2, 2, 2]}, {"ex": "3dc4eaa8-bfcd-4d0a-ab66-ea2350f02e36", "reps": "3-5", "rest": 20, "rpe": null, "notes": "Plyo push-up · max intent", "sets": [3, 2, 3, 3, 3]}, {"ex": "60536284-7bfa-440f-8eba-11b756afbf66", "reps": "3-5", "rest": 120, "rpe": null, "notes": "Chin ups · max intent", "sets": [3, 2, 3, 3, 3]}], [{"ex": "453f0f6b-ab72-4b84-bd87-4e550dc8b159", "reps": "5 each leg", "rest": 30, "rpe": 7, "notes": "Box Step up · 65% 1RM · max intent · sets: 1 to 2", "sets": [1, 1, 2, 1, 1]}, {"ex": "7247942c-de28-4d75-aa52-bb47dfd7bc3d", "reps": "5 each leg", "rest": 30, "rpe": 8, "notes": "Single leg RDL + isometric hamstring · 80% 1RM · max intent · sets: 1 + 1 iso", "sets": [1, 1, 1, 1, 1]}, {"ex": "98fd1fe1-b126-4221-953b-18093c8f40ba", "reps": "5", "rest": 90, "rpe": 7, "notes": "Push press · 65% 1RM · max intent", "sets": [2, 2, 2, 2, 2]}], [{"ex": "3be8a64a-196f-43d7-b8b2-a8f5f3c096bf", "reps": "6-8 each leg", "rest": 15, "rpe": null, "notes": "Copenhagen adductor · controlled", "sets": [1, 1, 1, 1, 1]}, {"ex": "e8088efe-5f14-4578-bba5-6c3ac300c5da", "reps": "8-10 each side", "rest": 30, "rpe": null, "notes": "Pallof press · controlled", "sets": [1, 1, 1, 1, 1]}]]}$SPEC$::jsonb;
  notes text := $NOTE$Contrast Training (Breidablik phase 3): 5 vikna contrast-fasi - tungar lyftingar paradar vid plyometrics fyrir kraft og RFD. Push, Pull og Combo dagar. VBT-hradamarkmid og %1RM eru i athugasemd hverrar aefingar. Readiness: graenn=fullt, gulur=-20% rummal/-15% akefd, raudur=-40%/-30%.$NOTE$;
  team uuid := '1aaecc06-e675-4cb2-a903-e6500cc67ce8'; -- "Helgi Gudfinnsson" PT context
  creator uuid := '60b93b68-94fa-43a9-bdab-78b51056a7fb';
  sess_keys text[]; sess_days int[]; sess_split text[]; sess_names text[];
  wk int; si int; grp jsonb; e jsonb; so int; spwv int;
  wks jsonb; sess jsonb; grps jsonb; exs jsonb;
begin
  delete from training_plan_templates where team_id=team
    and name in ('Contrast Training — 3×/viku','Contrast Training — 4×/viku');
  foreach spwv in array array[3,4] loop
    if spwv=3 then
      sess_keys:=array['push','pull','combo1']; sess_days:=array[1,3,5];
      sess_split:=array['push','pull','full']; sess_names:=array['Push','Pull','Combo Push & Pull'];
    else
      sess_keys:=array['push','pull','combo1','combo2']; sess_days:=array[1,2,4,5];
      sess_split:=array['push','pull','full','full']; sess_names:=array['Push','Pull','Combo Push & Pull','Combo Push & Pull 2'];
    end if;
    wks:='[]'::jsonb;
    for wk in 1..5 loop
      sess:='[]'::jsonb;
      for si in 1..array_length(sess_keys,1) loop
        grps:='[]'::jsonb; so:=0;
        for grp in select jsonb_array_elements(spec->sess_keys[si]) loop
          exs:='[]'::jsonb;
          for e in select jsonb_array_elements(grp) loop
            so:=so+1;
            exs := exs || jsonb_build_object('exerciseId', e->>'ex', 'sets', (e->'sets'->(wk-1)),
              'reps', e->>'reps', 'loadType','absolute_kg', 'loadValue',0, 'rpeTarget', e->'rpe',
              'tempo','', 'restSeconds', (e->>'rest')::int, 'notes', e->>'notes', 'sortOrder', so);
          end loop;
          grps := grps || jsonb_build_object('label', chr(64 + jsonb_array_length(grps) + 1), 'exercises', exs);
        end loop;
        sess := sess || jsonb_build_object('dayOfWeek', sess_days[si], 'name', sess_names[si],
          'type','strength', 'method','contrast', 'bodySplit', sess_split[si],
          'groups', grps, 'estimatedDurationMin', 60);
      end loop;
      wks := wks || jsonb_build_object('week', wk, 'sessions', sess);
    end loop;
    insert into training_plan_templates(team_id, created_by, name, plan_type, duration_weeks,
      sessions_per_week, readiness_enabled, deload_volume_pct, deload_intensity_pct,
      recovery_volume_pct, recovery_intensity_pct, structure, notes)
    values (team, creator, 'Contrast Training — '||spwv||'×/viku', 'strength', 5, spwv,
      true, 80, 85, 60, 70, wks, notes);
  end loop;
end $MIG$;
